def solve_garland(n, s):
    def count_recolors(color):
        recolor_count = 0
        for i in range(n):
            if i % 3 == color:
                if s[i] != 'RGB'[i % 3]:
                    recolor_count += 1
            elif s[i] != 'RGB'[(i-1) % 3]:
                recolor_count += 1
        return recolor_count

    min_recolors = float('inf')
    best_garland = ''

    for start in range(3):
        recolor_count = count_recolors(start)
        if recolor_count < min_recolors:
            min_recolors = recolor_count
            best_garland = ''.join('RGB'[(i+start) % 3] if (i-start) % 3 == 0 else s[i] for i in range(n))

    return min_recolors, best_garland

