def make_garland_nice(n, s):
    # Initialize counters for recoloring each position to a specific color
    recolor_count = [0] * n

    # Calculate minimum recolors needed for each position
    for color in 'RGB':
        current_recolor = 0
        # Forward pass
        for i in range(n):
            if s[i] != color:
                current_recolor += 1
            recolor_count[i] += current_recolor
            if i >= 2:
                current_recolor -= (s[i-2] != color)

        current_recolor = 0
        # Backward pass
        for i in range(n-1, -1, -1):
            if s[i] != color:
                current_recolor += 1
            recolor_count[i] = min(recolor_count[i], current_recolor)
            if i <= n-3:
                current_recolor -= (s[i+2] != color)

    # Find the minimum number of recolors needed
    min_recolors = min(recolor_count)

    # Reconstruct one of the possible nice garlands
    result = [''] * n
    current_recolor = 0
    for i in range(n):
        if recolor_count[i] == min_recolors:
            result[i] = 'RGB'[i % 3]
        else:
            if s[i] == 'RGB'[(i+1) % 3]:
                result[i] = 'RGB'[(i+1) % 3]
            elif s[i] == 'RGB'[(i+2) % 3]:
                result[i] = 'RGB'[(i+2) % 3]
            else:
                result[i] = s[i]

    print(min_recolors)
    print(''.join(result))

