def solve_garland_problem():
    n = int(input())
    s = input().strip()

    def count_recolors(color):
        return sum(1 for i in range(0, n, 3) if s[i] != color)

    best_color = min('RGB', key=count_recolors)
    recolors = count_recolors(best_color)

    result = [best_color] * n
    for i in range(1, n, 3):
        result[i] = 'RGB'.replace(best_color, '')[0]

    print(recolors)
    print(''.join(result))

